(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zk-sj-prepa-ped-j3-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zk-sj-prepa-ped-j3-idesfm\",\n \"titre\": \"Préparation D.E (J) · J3 Pédiatrie IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J3 (IDE/SFM) · J3 et J10 identiques\",\n     \"slug\": \"prepa-ped-j3-idesfm\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Nouveau-né GG, sexe masculin, est âgé de 5 jours. Il vit avec sa mère à Grand Yapo. La mère réalise les soins du cordon avec une décoction de plante traditionnelle. L'examen somatique de GG est normal. La réalité personnelle de GG comporte :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"données de dépendance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"5 données de dépendance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 données de dépendance\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2 données de dépendance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 2 données de dépendance\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'examen étant normal, on ne retient que deux éléments de dépendance : le très jeune âge (5 jours : le nouveau-né dépend entièrement de sa mère, source de difficulté « manque de force ») et les soins du cordon par décoction traditionnelle (danger d'infection et de tétanos ombilical, lié à un manque de connaissance de la mère). Les autres données (sexe, lieu de vie, examen normal) sont des données d'indépendance. Remarque : Dans le sujet, la première option n'indique pas de nombre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Introduction au raisonnement clinique — Diagnostic infirmier (Analyse et interprétation des données) ; Nouveau-né normal — Rôles de soins après la naissance\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie réalisée au premier trimestre de la grossesse vise les objectifs suivants sauf un. Cocher l'intrus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Confirmer la grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Estimer le risque trisomie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Apprécier l'activité cardiaque de l'embryon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rechercher des malformations\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Rechercher des malformations\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'échographie du 1er trimestre confirme la grossesse, apprécie l'activité cardiaque de l'embryon et estime le risque de trisomie (clarté nucale). La recherche des malformations est l'objectif de l'échographie du 2e trimestre : c'est l'intrus. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants sont ceux du kwashiorkor sauf un. Lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Enfant grognon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ulcération et desquamation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Alopécie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bouffissure du visage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Alopécie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le kwashiorkor associe enfant grognon, bouffissure du visage et œdèmes, ulcérations/desquamations et cheveux secs, fins, cassants puis roux (décolorés). L'alopécie avec cheveux normaux non décolorés est un signe du marasme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Kwashiorkor et Marasme\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les cellules qui produisent le lait maternel sont appelées :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cellules souches\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cellule épidermique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cellules épithéliales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cellules myoépithéliales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Cellules épithéliales\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le lait est produit par les cellules épithéliales sécrétrices des alvéoles (acini) sous l'effet de la prolactine ; les cellules myoépithéliales se contractent sous l'effet de l'ocytocine pour éjecter le lait. (explication partiellement hors cours du projet)\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Allaitement maternel », Physiologie de la lactation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"BH est âgé de 2 ans et pèse 12 kg. Il est correctement nourri. Sa surface corporelle est estimée à :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,2 m2\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"0,4 m2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0,5 m2\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"0,6 m2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 0,5 m2\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pour un enfant de 12 kg, la surface corporelle est d'environ 0,5 m² (formule (4 × P + 7) ÷ (P + 90) = 55 ÷ 102 ≈ 0,54 m²). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'infection bactérienne du nouveau-né précoce survient entre :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0 et 7 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"7 et 8 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8 et 16 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"16 et 28 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 0 et 7 jours\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"On distingue l'infection précoce ou materno-fœtale, qui survient avant le 7e jour de vie, et l'infection tardive ou post-natale, qui survient après le 7e jour (jusqu'à J28).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections bactériennes du nouveau-né — Introduction (Définition) ; Néonatologie (module de formation), Infections néonatales — Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous collaborez à la réalisation des examens suivants en cas de fièvre aiguë, sauf un lequel :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémoculture\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"ECBU\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Analyse LCR\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sérodiagnostic de Widal et Félix\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Sérodiagnostic de Widal et Félix\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"En cas de fièvre aiguë mal tolérée, on demande goutte épaisse/frottis, NFS, glycémie, radiographie pulmonaire, analyse du LCR et ECBU (hémoculture selon le contexte). Le sérodiagnostic de Widal et Félix est réservé à la fièvre prolongée (fièvre typhoïde).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Prescription d'examens (fièvre mal tolérée / fièvre prolongée)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un enfant qui fait de la fièvre avec une bonne tolérance présente :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une conscience altérée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des marbrures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un faciès vultueux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un teint grisâtre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un faciès vultueux\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'enfant qui tolère sa fièvre a un faciès vultueux (rouge) et des téguments chauds, érythrosiques. Conscience altérée, marbrures et teint grisâtre sont des signes de mauvaise tolérance.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Examen physique – Signes de mauvaise tolérance\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une femme rhésus négatif accouche d'un enfant rhésus positif. Elle n'a pas eu le sérum anti-D. Dans une telle situation le nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Doit téter les seins comme les autres enfants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ne doit pas téter les seins comme les autres enfants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Doit être nourri au biberon\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Doit recevoir le sérum anti tétanique en sous cutané\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Ne doit pas téter les seins comme les autres enfants\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Ne doit pas téter les seins ». Le cours dit seulement qu'il faut administrer le sérum anti-D à la mère rhésus négatif dans les 72 heures qui suivent l'accouchement d'un bébé rhésus positif, pour protéger la grossesse suivante (incompatibilité fœto-maternelle rhésus).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Ictère du nouveau-né — Rôles préventifs ; Cours de santé infantile L1 IDE-SFM, Examen du nouveau-né — Besoin de manger et boire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de risques de survenue des convulsions, liés à l'enfant sont les suivants, sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faible poids de naissance\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Céphalhématome\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Traumatisme crânien\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Malnutrition\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Céphalhématome\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les facteurs favorisants des convulsions sont la souffrance cérébrale néonatale, l'ictère nucléaire, l'infection néonatale, les séquelles neurologiques de maladies (méningite, neuropaludisme, malnutrition), la fièvre élevée et les antécédents familiaux. Le céphalhématome est une collection de sang sous le périoste, bénigne, qui ne touche pas le cerveau : il n'expose pas aux convulsions. Remarque : Le faible poids de naissance et le traumatisme crânien ne figurent pas mot à mot dans la liste du cours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Épidémiologie (Facteurs favorisants) ; Traumatismes obstétricaux — Céphalhématome\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les rôles de collaboration dans la prise en charge des convulsions sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Administrer le diazépam\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Récupérer des résultats de laboratoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prendre une voie veineuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aider la mère à allaiter\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Administrer le diazépam\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le diazépam (0,5 mg/kg en intrarectal ou IV lente) est administré pour arrêter la crise : c'est un médicament, donc un soin réalisé sur prescription (rôle délégué ou de collaboration). Aider la mère à allaiter est un rôle propre. Remarque : La prise d'une voie veineuse est elle aussi faite « sur indication médicale » dans le cours ; la question n'accepte qu'une seule réponse.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Convulsions de l'enfant — Rôle de soins curatifs ; Introduction au raisonnement clinique — Plan de soins (Interventions)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"ML est âgé de 36 mois, sa mère l'amène aux urgences pour une diarrhée glaireuse. Le germe probable à l'origine de cette diarrhée est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Schigelles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Eschérichia coli\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Vibrion cholérique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rotavirus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Schigelles\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une diarrhée glaireuse (glairo-sanglante) chez un enfant de 3 ans évoque une dysenterie à Shigella (mécanisme invasif). E. coli et le vibrion donnent surtout des diarrhées liquides ; le rotavirus touche surtout le nourrisson.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Etiologie et Pathogénie\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mère de JK n'a pas respecté la prescription médicale, et il présente 4 jours plus tard un poids de 8 kg, les yeux enfoncés, la bouche sèche et des signes évidents de déshydratation. Quelle est la quantité de SRO à administrer :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"500 ML\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"600 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"700ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 600 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Signes évidents de déshydratation : plan B, 75 ml/kg de SRO en 4 heures. 75 × 8 kg = 600 ml.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan B » (poids × 75)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La diarrhée aiguë concerne l'émission d'au moins 3 selles liquides par 24 heures depuis moins de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"21 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"14 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"8 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 14 jours\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La diarrhée aiguë est l'émission d'au moins 3 selles liquides par 24 heures depuis moins de 14 jours.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plan de traitement des signes sévères de déshydratation est le :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Plan A\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plan B\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Plan C\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Plan D\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Plan C\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Pas de signes : plan A ; signes évidents : plan B ; signes sévères : plan C (perfusion de Ringer lactate à l'hôpital). Il n'existe pas de plan D.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Diagnostic de gravité (tableau)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"DG est incapable de nouer les lacets de sa paire de tennis mais s'habille seul et raconte de petites histoires. Je conclus que DG est âgé de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4 ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 4 ans\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Vers 4 ans, l'enfant s'habille seul sauf les lacets de ses chaussures, connaît l'usage des objets familiers et raconte de petites histoires ; il lace ses chaussures vers 5-6 ans.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Annexes, « Principales étapes du développement psychomoteur » (4 ans)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes concernent les signes d'un enfant souffrant de marasme. Cochez la proposition qui est retrouvée au stade de début de cette maladie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fonte graisseuse et musculaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Retard pondéral inférieur à 60% du poids idéal théorique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Affamé et porte le doigt à la bouche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Alopécie avec le reste des cheveux normaux non décolorés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Affamé et porte le doigt à la bouche\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Au début du marasme, la croissance stagne, l'enfant est affamé, porte ses doigts à la bouche et pleure sans cesse. La fonte graisseuse, le retard pondéral < 60 % et l'alopécie apparaissent à la phase d'état.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Malnutrition de l'enfant », Formes cliniques – Marasme\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les propositions suivantes sont relatives à la bonne pratique de la réanimation du nouveau-né en salle de naissance sauf une. Cocher cette proposition\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Essuyer l'enfant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vérifier la respiration\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Porter un bonnet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pincer le mamelon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Pincer le mamelon\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Essuyer, vérifier la respiration et mettre un bonnet sont de bonnes pratiques (contrôle de la température et de la respiration). Pincer le mamelon est un geste brutal à proscrire.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Réanimation du nouveau-né en salle de naissance », Gestes dangereux à proscrire\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les séquelles neurologiques et neurosensorielles au cours du paludisme sont les suivantes sauf une, laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Paralysie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Troubles du tonus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Myosite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hypoacousie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Myosite\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les séquelles du paludisme grave neurologique sont la surdité, l'aphasie, la paralysie, les troubles du tonus et les difficultés scolaires. La myosite n'en fait pas partie.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Problèmes et devenir\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paludisme grave est causé par l'espèce plasmodiale suivante :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vivax\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ovale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Knowlésie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Falciparum\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Falciparum\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Seul Plasmodium falciparum est responsable des formes graves de paludisme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de mauvais pronostic au cours de la méningite purulente sont les suivants, sauf un lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Âge de moins de 5 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Virulence du germe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Malnutrition\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Retard de diagnostic et prise en charge\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Malnutrition\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Malnutrition » comme intrus. Les éléments de mauvais pronostic du cours sont : le très jeune âge, la nature du germe (pneumocoque et Haemophilus les plus virulents), un traitement antérieur, l'existence de facteurs favorisants, le retard au diagnostic et les complications.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Méningites bactériennes de l'enfant — Épidémiologie (Facteurs favorisants et de gravité) ; Problèmes et devenir (Devenir)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les principaux virus responsables des infections respiratoires aiguës sont les suivants, sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Virus para influenzae\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Herpès simplex virus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rhinovirus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Virus respiratoire syncytial\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Virus respiratoire syncytial\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Virus respiratoire syncytial ». Le cours cite comme virus fréquents des IRA : le virus para-influenzae, le virus respiratoire syncytial (VRS) et le rhinovirus.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections respiratoires aiguës de l'enfant — Épidémiologie (Germes)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ces affirmations concernant la bronchiolite sont justes sauf une. Laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Causée par Virus respiratoire Syncitial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Respiration sifflante\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fièvre et rhume\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Plus fréquent après 2 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Causée par Virus respiratoire Syncitial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient a. Le cours décrit la bronchiolite comme une maladie du nourrisson (1 mois à 2 ans), due au VRS, avec toux, polypnée, wheezing (respiration sifflante), râles, fièvre modérée et rhume.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections respiratoires aiguës de l'enfant — Principales formes étiologiques des IRA basses (Bronchiolite)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la prise en charge de la bronchiolite, l'agent de santé a pour rôle propre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Conseils à la mère sur l'hygiène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Montrer la technique de la DRP à la mère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Accompagner l'enfant en ORL\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Administrer antipyrétique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Montrer la technique de la DRP à la mère\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Montrer à la mère la désobstruction rhinopharyngée (lavage du nez au sérum physiologique) est un soin propre de l'agent de santé. Administrer un antipyrétique prescrit est un soin délégué ; accompagner en ORL relève de la collaboration.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Rhinopharyngite de l'enfant », Rôles curatifs ; « Plan de soins », Interventions\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les infections respiratoires basses sont les suivantes sauf une laquelle ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Bronchiolite aiguë\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sinusite maxillaire aiguë\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Laryngite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Bronchite aiguë\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Sinusite maxillaire aiguë\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les IRA basses touchent les bronches (bronchite), les bronchioles (bronchiolite) et le poumon (pneumopathie). La sinusite atteint les voies aériennes supérieures : c'est une IRA haute. Remarque : Selon le cours, la laryngite (c) est elle aussi une IRA haute : le sujet comporte donc deux intrus possibles.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Infections respiratoires aiguës de l'enfant — Introduction (Définition)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'administration de zinc comprimé dans le traitement de la diarrhée chez le nourrisson de moins de 6 mois est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 mg/j pendant 7 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"15 mg/j pendant 10 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10 mg/j pendant 5 jours\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"15 mg/j pendant 7 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 10 mg/j pendant 5 jours\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « 10 mg/j pendant 5 jours ». Le comprimé de zinc est dosé à 20 mg : avant 6 mois on donne ½ comprimé par jour, soit 10 mg/j.\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, Plan A : Donner du zinc ; L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Rôles curatifs (Médicaments)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La quantité de SRO à administrer chez un nourrisson, après chaque selle molle dans le plan A de traitement est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"50-100 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"25-50 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100-200 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Autant qu'il en voudra\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 50-100 ml\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Plan A : jusqu'à 2 ans, donner 50 à 100 ml de SRO après chaque selle liquide (100 à 200 ml à partir de 2 ans).\\n\\nSource : Livret de tableaux PCIMNE 0-5 ans, « Plan A : traiter la diarrhée à domicile »\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins propres dans la prise en charge des vomissements chez l'enfant sont les suivants, sauf un, lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nettoyer l'enfant\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Aider à alimenter l'enfant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Administrer du vogalène\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Surveiller l'enfant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Administrer du vogalène\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Nettoyer, aider à alimenter et surveiller l'enfant sont des soins propres. Administrer du Vogalène (antiémétique sur prescription) est un soin délégué : c'est l'intrus.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Vomissements de l'enfant », Rôles curatifs ; « Plan de soins », Interventions\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Tous les facteurs suivants inhibent le réflexe ocytocique chez la mère, sauf un. Cocher l'intrus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La vue de son bébé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La douleur physique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le manque de confiance en soi\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La crise d'anxiété\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le manque de confiance en soi\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Le manque de confiance en soi ». Le cours explique que la sécrétion d'ocytocine (éjection du lait) est favorisée par un climat de confiance et la sérénité de la mère ; le stress, la douleur et l'anxiété la freinent.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel — Physiologie de la lactation (Excrétion et éjection du lait) ; Cours de santé infantile L1 IDE-SFM, Allaitement — Physiologie de la lactation (Après l'accouchement)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant expatrié, venant pour la première fois dans une zone endémique est à risque de faire le paludisme\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'enfant expatrié non immun arrivant en zone d'endémie n'a pas de prémunition : il est à risque de paludisme (et de forme grave).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Facteurs favorisants\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un encombrement de l'arbre respiratoire au niveau de la zone de conduction se manifeste par une perturbation au niveau des échanges gazeux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un encombrement des voies aériennes empêche l'air d'atteindre les alvéoles : il retentit sur les échanges gazeux. Le glossaire précise que la perturbation des échanges gazeux peut découler d'un dégagement inefficace des voies respiratoires.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Glossaire du diagnostic infirmier, « Perturbation des échanges gazeux »\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paracétamol est administré à la posologie de 15 mg par kilogramme toutes les 6 heures si fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Paracétamol : 60 mg/kg/jour répartis en 4 prises, soit 15 mg/kg toutes les 6 heures.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Moyens médicamenteux\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'anorexie du nourrisson est un trouble du comportement alimentaire consécutif à une cause organique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'anorexie du nourrisson est un trouble du comportement alimentaire retenu seulement après avoir éliminé les causes organiques ; elle est liée à un conflit mère-enfant. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Anorexie du nourrisson », Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le sevrage précoce est un facteur favorisant la survenue de l'anémie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les erreurs diététiques (mauvaise conduite de la diversification et du sevrage) et les substituts du lait maternel favorisent l'anémie de l'enfant.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Anémie aiguë de l'enfant », Facteurs favorisants liés à l'environnement\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pose d'une transfusion sanguine est un rôle de collaboration\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La transfusion est faite sur indication médicale : l'agent de santé prélève le groupe sanguin, fait le test de compatibilité au lit du malade, calcule le débit et surveille l'enfant en lien avec le médecin.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Anémie aiguë de l'enfant — Rôle de soins curatifs (3e situation)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson allaité qui émet 3 à 4 selles par jour souffre d'une diarrhée aiguë\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Même question que la n° 36 : 3 à 4 selles par jour chez un nourrisson allaité ne sont pas une diarrhée. Faux. Remarque : cette question est la même que la question 36 du sujet ; la réponse est identique (Faux).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Diagnostic différentiel\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une fièvre qui évolue depuis 15 jours est une fièvre prolongée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une fièvre qui dure plus d'une semaine et moins d'un mois est une fièvre prolongée ; au-delà d'un mois, elle est chronique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laisser l'enfant avec sa mère 10 heures par jour est l'une des conditions de l'initiative Hôpitaux Amis des Bébés (IHAB)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La 7e règle de l'IHAB est de laisser l'enfant avec sa mère 24 heures sur 24, pas 10 heures par jour. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Allaitement maternel », Dix règles de l'Initiative Hôpitaux Amis des Bébés\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'électrophorèse de l'hémoglobine fait partie du bilan prénatal recommandé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'électrophorèse de l'hémoglobine (ou test d'Emmel) fait partie des examens recommandés du bilan prénatal.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre IV « Soins essentiels aux nouveau-nés », Soins maternels\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson allaité qui émet 3 à 4 selles par jour souffre d'une diarrhée aiguë\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Même question que la n° 36 : 3 à 4 selles par jour chez un nourrisson allaité ne sont pas une diarrhée. Faux. Remarque : cette question est la même que la question 36 du sujet ; la réponse est identique (Faux).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Diarrhée aiguë et déshydratation de l'enfant », Diagnostic différentiel\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La lèvre inférieure du bébé éversée et l'aréole peu visible en haut est un critère de bon positionnement au sein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La lèvre inférieure éversée et l'aréole peu visible en haut sont des critères d'une bonne PRISE du sein, pas du positionnement. Le positionnement concerne le dos sur l'avant-bras, la nuque dans le pli du coude, le ventre contre celui de la mère. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Allaitement maternel », Aide à l'allaitement\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le surfactant est un film tensioactif sécrété par les cellules pneumocytes I des poumons\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le surfactant est sécrété par les pneumocytes de type II (et non de type I). Faux.\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre II « Adaptation à la vie extra-utérine », Sécrétion du surfactant\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'entérocolite est un problème lié à la prématurité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'entérocolite ulcéro-nécrosante est une complication digestive de la prématurité (facteur de risque : faible âge gestationnel).\\n\\nSource : Module de néonatologie (Néonatalogie), Chapitre VIII « Prématurité », Complications digestives\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le manque de soutien psychologique de la mère est un facteur de déclin de l'allaitement exclusif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le manque de soutien psychologique de la mère allaitante est cité parmi les facteurs de déclin de l'allaitement.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Allaitement maternel », Politique de l'allaitement – Facteurs de déclin\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enveloppement humide est un rôle propre de l'agent de santé dans la prise en charge de la fièvre chez l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'enveloppement partiel avec un linge mouillé est un moyen physique de lutte contre la fièvre que l'agent de santé (et la mère) applique sans prescription : c'est un soin propre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Moyens physiques ; Les 12 pratiques familiales essentielles (PFE), PFE n° 9\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Des crises convulsives subintrantes sans reprise de la conscience inter-critique réalisent un état de mal convulsif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'état de mal convulsif est une crise de plus de 30 minutes ou une succession de crises pendant plus de 30 minutes sans reprise de conscience entre les crises.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Convulsions de l'enfant », Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hyperparasitémie supérieure à 4% chez le sujet immun est un critère clinique de gravité du paludisme grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hyperparasitémie fait partie des critères de gravité du paludisme définis par l'OMS (critères révisés en 2000). Remarque : Le cours ne donne pas de seuil chiffré. En connaissances générales, le seuil de 4 % est retenu pour le sujet non immun ; de plus, c'est un critère biologique et non clinique.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant — Étude clinique (Paludisme grave : manifestations biologiques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"JL a 4 ans, il présente seulement une fièvre et 2 vomissements ce jour. Le TDR paludisme réalisé est positif. Le traitement à administrer est l'Artéméther injectable.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Fièvre et 2 vomissements sans signe de danger (il ne vomit pas tout) : paludisme simple, traité par voie orale (artésunate + amodiaquine). L'artéméther injectable est réservé au paludisme grave. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Paludisme de l'enfant », Rôle de soins curatifs – 1re situation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le stress et le manque d'affection favorisent les vomissements du nourrisson\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le conflit entre les parents, le stress et le manque d'affection favorisent les vomissements, notamment psychogènes.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Vomissements de l'enfant », Facteurs favorisants liés à l'environnement\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le temps de recoloration cutané supérieur à 3 secondes est un signe de bonne tolérance de la fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un temps de recoloration cutanée allongé (> 3 secondes) est un signe de MAUVAISE tolérance de la fièvre. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Signes de mauvaise tolérance\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les téguments chauds et érythrosiques sont des signes de bonne tolérance de la fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Des téguments chauds et érythrosiques (faciès vultueux) témoignent d'une bonne tolérance de la fièvre, contrairement à la pâleur, aux marbrures ou au teint grisâtre.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Examen physique\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le syndrome extrapyramidal qui survient chez l'enfant après administration de l'antiémétisant se traite avec du diazépam\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Faux ». Les antiémétiques (métoclopramide, métopimazine…) peuvent provoquer un syndrome extrapyramidal chez l'enfant.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Vomissements de l'enfant — Rôles de soins (Rôles curatifs : antiémétisants)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nourrisson présentant une diarrhée aiguë sans signe de déshydratation boit avec avidité :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Vrai ».\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Diarrhée aiguë et déshydratation — Diagnostic de gravité (Tableau n°1 : classification) ; Livret de tableaux PCIMNE 0-5 ans, Évaluer la déshydratation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'Haemophilus influenzae est l'un des principaux germes responsables de la méningite bactérienne\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les trois principaux germes des méningites purulentes sont le pneumocoque, Haemophilus influenzae type b et le méningocoque.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Méningites bactériennes de l'enfant », Germes\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j3-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant une fièvre aiguë, vous collaborez avec le médecin à la réalisation d'un tubage gastrique BK\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le tubage gastrique à la recherche du BK fait partie du bilan d'une fièvre PROLONGÉE ou chronique (primo-infection tuberculeuse), pas d'une fièvre aiguë. Faux.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), « Fièvre de l'enfant », Prescription d'examens – Fièvre prolongée ou chronique\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J3 Pédiatrie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
